export const enclosureInformation = `<p class="detail-lead">一层一层，看清设备的结构。</p><ol class="detail-steps"><li><h3>顶盖</h3><p>覆盖上方硬件，与底壳形成完整外形。首页展示合拢状态，这里的分解视图将它抬起，便于观察内部。</p></li><li><h3>双层主板</h3><p>上层负责采集与控制，下层负责供电与驱动。图中的间距经过拉开，用来说明装配关系，不代表实际安装间隙。</p></li><li><h3>底壳</h3><p>容纳主板与连接部件，保留模型中的侧面开口、壳体接缝与底部支脚。</p></li></ol><p class="detail-footnote">结构依据当前 CAD 模型展示；网页中的暖白塑料外观用于产品预览，实物材料与表面工艺以实际制作版本为准。</p>`;

export const overview = `<p class="detail-lead">数据从填写开始，从本地发送到浏览器和设备。</p><ul class="detail-list"><li><strong>基础信息输入</strong><p>输入植物、地点、栽培方式、光照与水源等基础信息，并根据外部 API 自动查询天气。</p></li><li><strong>本地换算</strong><p>按照植物与地点知识库换算参数，生成一份临时配置，再由浏览器校验格式与范围。</p></li><li><strong>留存写入</strong><p>配置经蓝牙写入 ESP32-C3，由设备保存后独立运行，页面上的需求曲线只留在本地。</p></li></ul><a class="detail-action" href="#product">看设备如何使用这份配置 →</a>`;

export function connectionInformation(compatible) {
 return `<p class="detail-lead">经过唤醒、授权和握手后，配置才开始传输。</p><ol class="detail-steps"><li><h3>唤醒设备</h3><p>设备深度休眠时蓝牙不工作，网页无法唤醒，需要手动按下外置按钮再继续。</p></li><li><h3>在浏览器中选择设备</h3><p>打开系统蓝牙，点击“连接浇水设备”，在设备列表里选中设备并连接。</p></li><li><h3>握手完成后写入</h3><p>连接建立后核对设备与固件版本，与设备握手后读取状态或写入配置。</p></li></ol><div class="detail-note"><strong>${compatible ? '当前浏览器提供蓝牙接口' : '当前浏览器未提供蓝牙接口'}</strong><p>${compatible ? '连接仍取决于系统蓝牙、用户授权与匹配的固件。设备休眠或断开后，重新唤醒再连一次。' : '请改用支持 Web Bluetooth 的浏览器，并运行在 localhost 或 HTTPS 下；现在只提供这一种连接方式。设备休眠或断开后，重新唤醒再连一次。'}</p></div>`;
}

export const workspaceInformation = `<p class="detail-lead">设备会记录异常和特殊事件。</p><ul class="workspace-links detail-list"><li><a href="#product"><strong>需求归零</strong><span>雨量、土壤无效或季节间隔未到时，浇水需求被归零或推迟，泵不动不是故障</span><b aria-hidden="true">→</b></a></li><li><a href="#configure"><strong>写入被拒</strong><span>参数或版本不匹配时，设备会拒绝写入，继续按旧配置运行</span><b aria-hidden="true">→</b></a></li><li><a href="#device"><strong>事件登记</strong><span>级别、通道、依据与控制影响都记在设备页，恢复以复测结果为准</span><b aria-hidden="true">→</b></a></li></ul><p class="detail-footnote">事件由设备记录，未复测前不要当成已恢复；模拟设备只做演示，不会写入真实硬件。</p>`;

export const principleInformation = `<p class="detail-lead">自动浇水出问题，线索通常落在四个环节：读数、需求、条件、出水。</p><ul class="detail-list"><li><strong>读数不可信</strong><p>土壤与雨量先多次采样取中位数，压住抖动。读数仍然无效时，自动浇水需求直接归零，泵不会启动。</p></li><li><strong>需求值被误读</strong><p>土壤原始 ADC 按 0–4095 归一化，与温度胁迫、空气干燥度合成 0–100 的相对需求。它不是土壤湿度百分比。</p></li><li><strong>启动条件没满足</strong><p>检测到下雨、未达配置阈值、季节间隔未到，或上一轮浇水还没结束，任一情况都会让泵停住。</p></li><li><strong>出水量与预期不符</strong><p>脉冲浇水按“开泵—等待—再次开泵”执行，实际水量取决于水泵流量、开泵时间和脉冲次数。</p></li></ul><div class="detail-note"><strong>网页配置，设备决策</strong><p>网页根据植物、地点、栽培方式、光照与水源生成临时配置；浏览器通过 BLE 写入设备。配置保存后，设备独立采样、判断与运行，不需要持续打开网页。</p></div>`;

export const hardwareInformation = `<p class="detail-lead">判断在上板完成，供能与出力在下板，两块板通过一组连接器交换信号。</p><div class="board-comparison"><figure><img src="/static/assets/boards/upper-10-01.png" alt="10-01 版本上板正面 PCB 工程图" loading="lazy"><figcaption>上板 · 采集与控制</figcaption></figure><figure><img src="/static/assets/boards/lower-10-01.png" alt="10-01 版本下板正面 PCB 工程图" loading="lazy"><figcaption>下板 · 供电与驱动</figcaption></figure></div><ul class="detail-list"><li><strong>上板：采集并判断</strong><p>带 OLED 的 ESP32-C3 经插座装在上板，温湿度、土壤、雨量传感器与太阳能电压采样都接在这里。传感器共用受控电源，读完就断电。</p></li><li><strong>下板：供能与驱动</strong><p>下板布置 18650 电池座、电源连接、开关与保护器件。AO3400A 驱动水泵，续流二极管吸收关泵时的感性负载，舵机单独走接口。</p></li><li><strong>板间：电源与信号的通道</strong><p>电源、地、水泵、舵机与太阳能相关信号都从这里通过。系统按 5V 设计，电源模块的带载能力要随整机验证。</p></li><li><strong>执行器：按信号动作</strong><p>水泵以低电平开启、高电平关闭，负责浇水；舵机负责擦拭雨量板。</p></li></ul><p class="detail-footnote">依据浇水6代-v2 的 10-01 版本资料，图片为 PCB 工程图。太阳能输入电压可采样；电池电量与系统 VIN 没有独立测量通道。</p>`;

export const workflowInformation = `<p class="detail-lead">异常会顺着这个顺序暴露，哪一步停住，问题就在哪一段。</p><ol class="detail-steps"><li><h3>启动与准备</h3><p>加载保存的配置，先保持水泵关闭、传感器电源关闭，再初始化显示、采样与通信。</p></li><li><h3>供电与采样</h3><p>开启传感器电源，等待稳定，读取温湿度、土壤、雨量及太阳能输入电压；传感器采样结束后断电。</p></li><li><h3>判断与执行</h3><p>检查数据有效性、降雨、需求阈值与季节间隔。满足条件时执行脉冲浇水；雨量板擦拭由舵机负责。</p></li><li><h3>记录与休眠</h3><p>记录采样与运行结果，关泵并完成动作收尾。长期模式随后进入深度休眠，等待下一次唤醒。</p></li></ol><h3 class="detail-subheading">选择适合当前阶段的模式</h3><dl class="detail-modes"><div><dt>DISPLAY <span>展示 / 调试</span></dt><dd>观察采样与 OLED 显示，资料默认约每 2 秒采样一次。</dd></div><div><dt>PREPARE <span>准备 / 采样</span></dt><dd>正式运行前采集基准，资料默认准备窗口约 10 分钟。</dd></div><div><dt>LONGRUN <span>长期运行</span></dt><dd>周期唤醒、采样与必要浇水，资料默认约每 2 小时唤醒一次。</dd></div></dl><p class="detail-footnote">时间为资料中的默认行为，实际参数与可用操作以当前固件及设备反馈为准。</p>`;

export const guideInformation = `<p class="detail-lead">从接线到长期运行，五步走完首次使用。</p><ol class="detail-steps"><li><h3>接好传感器与水路</h3><p>核对供电、板间连接、水泵与舵机接口；准备水源并确认出水位置，各负载分别试一遍。</p></li><li><h3>检查传感器读数</h3><p>查看温湿度、土壤与雨量原始 ADC 和太阳能 ADC 电压；改变实际输入并确认读数变化，单独测试水泵和舵机。</p></li><li><h3>唤醒设备并连接</h3><p>按外置按钮唤醒设备，用支持 Web Bluetooth 的浏览器连接，等握手成功。</p></li><li><h3>生成配置并写入</h3><p>在个性化库编译页填写植物、地点、光照、栽培方式与水源；核对推荐参数后下发，确认设备完成校验与保存。</p></li><li><h3>验证后转入长期运行</h3><p>用 DISPLAY 看读数，用 PREPARE 取基准；确认出水、土壤状态与反馈后启用 LONGRUN，再翻看近期记录。</p></li></ol><div class="detail-note"><strong>核对实际运行效果</strong><p>设备采用固定板级参数，网页按植物库和种植场景生成控制配置。核对实际触发状态与出水量，再调整种植配置。</p></div><a class="detail-action" href="#configure">开始配置你的种植场景 →</a>`;
